-- Points clés en tête de fiche (recette 2.2-1 : 3 à 5 points clés).
--
-- Propositions rédigées le 01/10/2026 à partir du contenu de chaque fiche, à
-- valider par un médecin avant affichage :
--   - points_cles_propositions : une ligne par fiche (points proposés,
--     statut proposee / validee / refusee) ;
--   - valider_points_cles(doc_id, points) : validateur ; 3 à 5 points,
--     éventuellement retouchés, enregistrés dans documents.points_cles et
--     tracés au journal ;
--   - refuser_points_cles(doc_id) : la proposition est écartée ;
--   - documents.points_cles n'est lisible que par le serveur, qui ne
--     l'affiche que sur une fiche ouverte au membre.
-- Idempotent.

alter table public.documents add column if not exists points_cles jsonb;

create table if not exists public.points_cles_propositions (
  document_id uuid primary key references public.documents(id) on delete cascade,
  fiche_key text not null,
  points jsonb not null check (jsonb_typeof(points) = 'array'),
  status text not null default 'proposee' check (status in ('proposee', 'validee', 'refusee')),
  decided_by uuid references public.profiles(id) on delete set null,
  decided_at timestamptz,
  created_at timestamptz not null default now()
);
create index if not exists points_cles_propositions_status_idx on public.points_cles_propositions (status, fiche_key);

alter table public.points_cles_propositions enable row level security;
revoke all on public.points_cles_propositions from public, anon, authenticated;
grant select on public.points_cles_propositions to authenticated;
grant all on public.points_cles_propositions to service_role;
drop policy if exists points_cles_select_equipe on public.points_cles_propositions;
create policy points_cles_select_equipe on public.points_cles_propositions for select
  to authenticated using (public.has_editorial_role('validateur'));

create or replace function public.valider_points_cles(doc_id uuid, points text[])
returns text language plpgsql volatile security definer set search_path = public
as $$
declare
  propres text[];
begin
  if auth.uid() is null or not public.has_editorial_role('validateur') then
    raise exception 'Réservé aux validateurs' using errcode = '42501';
  end if;
  select coalesce(array_agg(btrim(p) order by o), '{}') into propres
    from unnest(points) with ordinality as t(p, o)
   where btrim(p) <> '';
  if cardinality(propres) < 3 or cardinality(propres) > 5
     or exists (select 1 from unnest(propres) p where char_length(p) > 400) then
    return 'points_invalides';
  end if;
  if not exists (select 1 from public.points_cles_propositions where document_id = doc_id) then
    return 'introuvable';
  end if;
  update public.documents set points_cles = to_jsonb(propres) where id = doc_id;
  update public.points_cles_propositions
     set status = 'validee', points = to_jsonb(propres), decided_by = auth.uid(), decided_at = now()
   where document_id = doc_id;
  insert into public.audit_log (actor_id, action, entity_type, entity_id, after)
  values (auth.uid(), 'points_cles_valides', 'documents', doc_id, jsonb_build_object('points', to_jsonb(propres)));
  return 'ok';
end;
$$;

create or replace function public.refuser_points_cles(doc_id uuid)
returns text language plpgsql volatile security definer set search_path = public
as $$
begin
  if auth.uid() is null or not public.has_editorial_role('validateur') then
    raise exception 'Réservé aux validateurs' using errcode = '42501';
  end if;
  update public.points_cles_propositions
     set status = 'refusee', decided_by = auth.uid(), decided_at = now()
   where document_id = doc_id and status = 'proposee';
  if not found then
    return 'introuvable';
  end if;
  insert into public.audit_log (actor_id, action, entity_type, entity_id)
  values (auth.uid(), 'points_cles_refuses', 'documents', doc_id);
  return 'ok';
end;
$$;

revoke all on function public.valider_points_cles(uuid, text[]) from public, anon;
revoke all on function public.refuser_points_cles(uuid) from public, anon;
grant execute on function public.valider_points_cles(uuid, text[]) to authenticated;
grant execute on function public.refuser_points_cles(uuid) to authenticated;

-- Propositions (fiche retrouvée par sa clé ; ignorées si la fiche n'existe pas).
insert into public.points_cles_propositions (document_id, fiche_key, points)
select d.id, v.fiche_key, v.points
from (values
  ('aap_endoprotheses_coronaires', '["Double antiagrégation après stent : au moins 4 à 6 semaines pour un stent nu, au moins 6 à 12 mois pour un stent pharmacoactif.", "L''arrêt des antiplaquettaires est un facteur de risque majeur de thrombose de stent.", "Si une chirurgie est prévue dans les 6 à 12 mois, un stent nu est préférable ; la chirurgie ultérieure doit être évoquée avant toute pose de stent pharmacoactif.", "Décision périopératoire collégiale obligatoire (cardiologue, hémostasien, opérateur, anesthésiste-réanimateur), guidée par la matrice risque thrombotique × risque hémorragique.", "Document de 2006 : se reporter aussi aux propositions GIHP/GFHT/SFAR 2018 sur les antiplaquettaires."]'::jsonb),
  ('aap_programmee', '["Classer d''abord la procédure selon son risque hémorragique : faible (réalisable sous bithérapie), intermédiaire (sous aspirine seule, cas le plus fréquent) ou élevé (impossible sous aspirine).", "Si l''interruption est indiquée : dernière prise d''aspirine à J-3, de clopidogrel et de ticagrélor à J-5, de prasugrel à J-7.", "Pas de relais des antiplaquettaires par héparine (HNF ou HBPM) ni par AINS.", "Aspirine au long cours jusqu''à 300 mg/j : ne pas réduire la dose avant la chirurgie ; l''arrêter si elle est prescrite en prévention primaire.", "Sans référentiel pour classer un acte, une équipe référente pluridisciplinaire de l''établissement définit la conduite."]'::jsonb),
  ('aap_urgence', '["Tenir compte de la molécule et de l''heure de la dernière prise : seul le ticagrelor est réversible, et aucun antidote spécifique n''existe.", "Aspirine : transfusion de plaquettes à 0,5 à 0,7 × 10¹¹ pour 10 kg en cas de besoin de neutralisation.", "Clopidogrel ou prasugrel : dose de plaquettes au moins double de celle de l''aspirine, efficacité réduite si la dernière prise date de moins de 6 heures.", "Tests fonctionnels plaquettaires : utiles dans les équipes formées (pontage semi-urgent, dysfonction suspectée), sans seuil consensuel ni usage systématique."]'::jsonb),
  ('allergie_prevention', '["Environ 60 % des réactions d''hypersensibilité immédiate en anesthésie sont IgE-dépendantes ; incidence de 1/10 000 à 1/20 000 anesthésies.", "Les curares sont la première cause d''anaphylaxie péranesthésique, devant le latex, les hypnotiques et les antibiotiques.", "Chez l''enfant, le latex est l''allergène le plus fréquent, surtout chez l''enfant multiopéré ou porteur de spina bifida : prévention primaire de la sensibilisation.", "Après une réaction : dosages biologiques immédiats (tryptase, histamine) puis tests cutanés, référence du diagnostic."]'::jsonb),
  ('alr_douleur_chronique', '["Morphine intrathécale en cas d''échec des traitements conventionnels, après sélection rigoureuse des patients [1+].", "Ziconotide intrathécal en première intention dans les douleurs réfractaires à composante neuropathique, avec titration lente [1+].", "Analgésie intrathécale dans les douleurs cancéreuses réfractaires malgré un traitement bien conduit [1+].", "ALR chez le patient amputé : meilleure analgésie postopératoire et moins de douleurs du moignon [1+].", "Pas de kétamine ni de midazolam par voie périmédullaire, faute de données toxicologiques."]'::jsonb),
  ('alr_non_specialiste', '["En urgence, l''ALR par le médecin non anesthésiste concerne surtout les traumatismes des membres et de la face.", "Le bloc iliofascial est la technique de référence en urgence pour la fracture de la diaphyse fémorale, sans neurostimulateur.", "Le bloc fémoral procure une analgésie prévisible et de qualité chez l''enfant comme chez l''adulte, en préhospitalier comme à l''hôpital.", "Respecter les doses maximales d''anesthésiques locaux, y compris en cumulé lors des réinjections ; prudence particulière chez l''enfant de moins d''un an."]'::jsonb),
  ('alr_pediatrie', '["Utiliser des anesthésiques locaux de type amino-amide, moins concentrés chez le nouveau-né et le nourrisson.", "Réduire les doses avant 2 ans, encore davantage avant 6 mois (immaturité hépatique) et en cas de réinjections.", "Privilégier la ropivacaïne 2 mg/ml ou la lévobupivacaïne 2,5 mg/ml ; en caudale, ne pas dépasser 2 mg/kg.", "Pas de clonidine périmédullaire chez le nouveau-né et le nourrisson sans surveillance continue (risque d''apnée).", "Morphiniques périmédullaires : aucune co-administration par une autre voie, surveillance continue chez le nouveau-né et le nourrisson."]'::jsonb),
  ('alr_pediatrique_2026', '["Échoguidage recommandé pour l''ALR périphérique de l''enfant [1+], et pour la caudale afin d''en améliorer la sécurité [2+].", "Clonidine ou dexmédétomidine à 1 µg/kg en périnerveux quand une analgésie prolongée est souhaitée [1+].", "ALR recommandée pour la chirurgie des fentes labio-palatines et la chirurgie abdominale profonde [1+].", "Morphine intrathécale recommandée pour l''analgésie des 24 premières heures après arthrodèse vertébrale [1+].", "Actualise la RFE pédiatrique de 2010 (enfants de 0 à 15 ans)."]'::jsonb),
  ('alr_perinerveuse', '["L''échoguidage est la technique de référence : il permet de réduire la dose d''anesthésique local et le risque de toxicité [1+].", "Ne pas ajouter de morphiniques, tramadol, naloxone ou magnésium aux anesthésiques locaux en périnerveux [1-].", "Intoxication systémique aux anesthésiques locaux : émulsions lipidiques IV en complément de la réanimation.", "AOD à dose curative hors urgence : dernière prise à J-3 avant l''ALR (J-4 ou J-5 pour le dabigatran).", "Le sepsis ne contre-indique pas l''ALR périnerveuse, à condition de ne pas ponctionner en zone infectée."]'::jsonb),
  ('amygdalectomie_enfant', '["Consultation d''anesthésie centrée sur les risques respiratoires et hémorragiques, avec une information adaptée à l''enfant et aux parents.", "Bilan d''hémostase (TCA, plaquettes) seulement si antécédents hémorragiques ou évaluation non fiable, notamment avant 3 ans.", "Une infection des voies aériennes supérieures augmente les complications respiratoires ; en cas de report, attendre au moins 3 semaines.", "Le SAOS représente environ deux tiers des indications ; un SAOS grave majore le risque respiratoire.", "Morphine IV en première ligne pour l''analgésie ; AINS déconseillés."]'::jsonb),
  ('anaphylaxie', '["Doser la tryptase au moins deux fois : entre 30 min et 2 h après le début des symptômes, puis au moins 24 h après leur résolution [1+].", "Tests cutanés avec toutes les substances administrées avant la réaction, aux concentrations recommandées [1+].", "Adresser en consultation d''allergo-anesthésie sur la suspicion clinique, sans attendre un score ni le résultat de la tryptase.", "Grade II ou plus : adrénaline associée à un remplissage vasculaire à débit élevé [1+]."]'::jsonb),
  ('anemie', '["Seuil transfusionnel restrictif à 7 g/dL d''hémoglobine en soins critiques, y compris en cas de sepsis [1+].", "Après chirurgie cardiaque : seuil de 7,5 à 8 g/dL [1+].", "Pas d''objectif libéral au-dessus de 10 g/dL chez le coronarien aigu ni chez le cérébrolésé.", "Réduire le nombre et le volume des prélèvements sanguins pour limiter l''anémie acquise.", "Agents stimulants de l''érythropoïèse possibles chez l''anémique ou le traumatisé sans contre-indication ; les arrêter quand l''hémoglobine atteint 10 à 12 g/dL."]'::jsonb),
  ('anesth_cardiopathie_congenitale', '["Évaluer le risque avec un score composite : type de cardiopathie, statut physiologique (A à D) et risque chirurgical.", "Score intermédiaire ou élevé : prise en charge en centre expert en cardiopathies congénitales.", "ALR titrée préférée à l''anesthésie générale quand elle est possible ; une procédure sous ALR périphérique est à faible risque.", "Monitorage adapté à la cardiopathie (PVC continue en cas de circulation de Fontan) et soins critiques postopératoires selon le risque."]'::jsonb),
  ('anesth_pediatrique_structures', '["Idéalement, bloc et SSPI pédiatriques dédiés ; personnel adapté à l''âge (anesthésiste assisté au minimum avant 1 mois).", "Pas d''hospitalisation d''un enfant de moins de 10 ans en réanimation adulte ; présence des parents facilitée.", "Matériel respiratoire adapté à toutes les tailles (masques et canules de 00 à 4, ballons auto-gonflables adaptés à l''âge).", "Hors centre pédiatrique, un chariot dédié regroupe le matériel adapté au poids et à l''âge de l''enfant."]'::jsonb),
  ('antibioprophylaxie', '["Injecter l''antibioprophylaxie (céphalosporine) au plus tôt 60 min avant l''incision et au plus tard avant celle-ci [GRADE 1].", "Vancomycine : perfusion sur 60 min, à débuter entre 60 et 30 min avant l''incision.", "Réinjecter la moitié de la dose initiale toutes les deux demi-vies si l''intervention se prolonge (céfazoline toutes les 4 h, céfuroxime toutes les 2 h).", "Ne pas prolonger l''antibioprophylaxie au-delà de la fin de l''intervention dans la très grande majorité des cas [GRADE 1]."]'::jsonb),
  ('antibiotherapie_probabiliste', '["Dans les états septiques graves, débuter l''antibiothérapie probabiliste en urgence, choisie selon le site infectieux.", "Purpura fulminans : C3G (céfotaxime ou ceftriaxone) IV immédiatement, avant même la ponction lombaire.", "Méningite avec signes de localisation : C3G + vancomycine, puis TDM et PL ; suspicion de listériose : amoxicilline + gentamicine.", "Réévaluer l''antibiothérapie à J2-J3 avec les résultats microbiologiques.", "Chez l''immunodéprimé et l''enfant, adapter la prise en charge (évolution plus rapide, pharmacocinétique différente)."]'::jsonb),
  ('anticoag_urgence', '["Hémorragie intracrânienne ou choc hémorragique sous anticoagulant : réverser sans attendre les résultats biologiques, sauf s''ils sont disponibles en quelques minutes [1+].", "Acide tranexamique selon les mêmes indications que chez le patient non anticoagulé, quelle que soit la gravité [1+].", "Hémorragie grave sous AVK avec INR > 1,5 (> 1,2 si hémorragie intracrânienne) : arrêt de l''AVK, CCP et 10 mg de vitamine K [1+].", "Procédure urgente sous AVK sans INR disponible : CCP 25 UI/kg + 5 mg de vitamine K IV, puis contrôle de l''INR à 30 min [1+].", "AVC ischémique sous AVK : thrombolyse possible si INR < 1,7 ; thrombectomie à envisager en cas d''occlusion proximale [1+]."]'::jsonb),
  ('anticoagulants', '["Décider en croisant le risque hémorragique de la procédure, le risque thromboembolique du patient et les conséquences d''un report.", "Procédure à faible risque : poursuivre l''AVK (INR contrôlé la semaine précédente) ; sous AOD, sauter la prise de la veille au soir et celle du matin, reprise ≥ 6 h après.", "Procédure à risque élevé : dernière prise d''AOD anti-Xa à J-3 (J-5 si neurochirurgie ou geste neuraxial) ; warfarine à J-6, fluindione à J-5, acénocoumarol à J-4, avec INR la veille.", "Reprendre l''AVK dans les 24 premières heures, à la dose habituelle, sans dose de charge ni relais héparinique [1+].", "Thromboprophylaxie veineuse post-procédurale en attendant la reprise de l''anticoagulation curative [1+]."]'::jsonb),
  ('aod_dabigatran_urgence_2016', '["L''idarucizumab (Praxbind®) est l''antidote spécifique du dabigatran : 5 g, sans adaptation à l''âge ni à la fonction rénale.", "Hémorragie dans un organe critique ou choc : idarucizumab si concentration > 50 ng/mL, ou si inconnue avec dernière prise ≤ 24 h ou ClCr ≤ 50 mL/min.", "Hémorragie grave : réaliser d''abord le geste hémostatique ; l''antidote seulement si le geste est impossible ou inefficace.", "Sans idarucizumab : CCP 50 U/kg ou FEIBA 30 à 50 U/kg, d''efficacité non formellement établie.", "Un temps de thrombine normal exclut une concentration significative de dabigatran ; un TCA ou un TQ normal ne l''exclut pas."]'::jsonb),
  ('aod_programme', '["Geste à faible risque hémorragique : ne pas prendre l''AOD la veille au soir ni le matin du geste, reprise au moins 6 h après.", "Geste à risque élevé : dernière prise à J-3 pour rivaroxaban, apixaban et edoxaban ; dabigatran à J-4 (ClCr ≥ 50 mL/min) ou J-5 (ClCr 30 à 50 mL/min).", "Pas de relais par héparine en préopératoire, pas de dosage systématique de l''AOD avant un geste programmé.", "Neurochirurgie intracrânienne et gestes neuraxiaux : arrêt plus long (dernière prise à J-5), schéma défini par une équipe référente."]'::jsonb),
  ('aod_urgence', '["Chirurgie urgente sous dabigatran ou rivaroxaban : opérer sans délai si la concentration est ≤ 30 ng/mL.", "Entre 30 et 200 ng/mL : attendre jusqu''à 12 h si possible ; sinon opérer et antagoniser en cas de saignement anormal (CCP ou FEIBA).", "Au-delà de 200 ng/mL : retarder l''intervention ; dialyse à discuter pour le dabigatran seulement.", "Document de 2013, antérieur aux antidotes (idarucizumab, andexanet alfa) : voir les recommandations plus récentes."]'::jsonb),
  ('asthme_aigu_grave', '["Les bêta-2 mimétiques sont la priorité du traitement, par voie inhalée en première intention.", "La nébulisation est supérieure à la voie IV pour le traitement initial ; chez l''enfant, aérosol-doseur avec chambre d''inhalation (5 à 10 bouffées de 100 µg) en première intention.", "Chez l''enfant, ajouter l''ipratropium : 3 nébulisations dans la première heure (250 µg avant 6 ans, 500 µg après).", "Corticoïdes sans posologie élevée ; pas d''aminophylline chez l''adulte.", "Toute crise avec signes de gravité impose le transfert en milieu hospitalier."]'::jsonb),
  ('avc_precoce', '["Devant des symptômes d''AVC, même régressifs, appeler le SAMU-Centre 15 ; le message FAST aide à reconnaître les signes.", "Noter l''heure exacte de début des symptômes et laisser le patient allongé.", "Tout déficit neurologique brutal, transitoire ou prolongé, est une urgence absolue ; l''AIT justifie une prise en charge neurovasculaire immédiate.", "Orienter vers une unité neurovasculaire, l''imagerie (IRM privilégiée) et la thrombolyse éventuelle, d''autant plus efficace qu''elle est précoce."]'::jsonb),
  ('blocs_perimedullaires_cesarienne_2006', '["Associer systématiquement un morphinique liposoluble à l''anesthésique local pour la césarienne sous anesthésie périmédullaire [A].", "Rachianesthésie obstétricale : aiguille pointe-crayon de diamètre ≤ 25G [A].", "Morphine intrathécale : pas de bénéfice au-delà de 80 à 100 µg, avec davantage d''effets secondaires [A].", "Prévention de l''inhalation : anti-H2 et citrate de sodium avant la césarienne ; jeûne de 6 à 8 h pour les solides en programmé.", "Surveillance de la pression artérielle toutes les minutes pendant l''induction de la rachianesthésie."]'::jsonb),
  ('blocs_perimedullaires_ci_2006', '["Trois prérequis : maîtrise de la technique, moyens de surveillance adaptés et consentement éclairé [A].", "Contre-indications absolues : refus du patient, et lidocaïne par voie intrathécale [A].", "Contre-indiqué aussi : allergie documentée à un agent injecté, patient non coopérant.", "Faute de consultation d''anesthésie préalable, ne pas refuser l''analgésie périmédullaire pour ce seul motif si la sécurité est assurée.", "Informer des risques habituels et des risques rares mais graves, remis dans leur contexte."]'::jsonb),
  ('blocs_perimedullaires_complications_2006', '["Les cristalloïdes ne suffisent pas à prévenir l''hypotension ; les colloïdes la réduisent davantage [A].", "Rachianesthésie obstétricale : vasopresseurs recommandés, et corriger toute baisse de pression artérielle.", "Traiter l''hypotension tôt par sympathomimétiques (éphédrine, phényléphrine, adrénaline) en bolus ou en perfusion ; pas d''éphédrine intramusculaire.", "Prévention des nausées et vomissements : dropéridol à faible dose (0,625 à 1,25 mg) ou ondansétron 8 mg [A]."]'::jsonb),
  ('blocs_perimedullaires_echec_2006', '["Diagnostiquer l''échec le plus vite possible, avant de débuter la chirurgie ou l''analgésie obstétricale.", "Le niveau d''analgésie au toucher est bien corrélé à la qualité de l''analgésie chirurgicale.", "Il faut au moins 30 à 50 péridurales et autant de rachianesthésies pour réduire nettement le taux d''échec.", "Durée insuffisante : ajouter un morphinique liposoluble ou 50 à 75 µg de clonidine [A].", "En cas d''échec ou de bloc incomplet : complément d''injection, nouvelle péridurale ou conversion en anesthésie générale."]'::jsonb),
  ('blocs_perimedullaires_hemostase_2006', '["Aspirine ou AINS seuls ne contre-indiquent pas une anesthésie périmédullaire [B].", "Thiénopyridines : contre-indication, avec arrêt d''au moins 10 jours du clopidogrel ou de la ticlopidine.", "Thrombopénie inférieure à 75 000 plaquettes ou thrombopathie associée : contre-indication.", "HNF sous-cutanée : attendre 12 h après la dernière injection (ou vérifier un TCA normal), reprise possible 6 à 8 h après le geste.", "Le risque d''hématome périmédullaire est très faible mais augmente nettement sous HNF ou HBPM."]'::jsonb),
  ('blocs_perimedullaires_infectieux_2006', '["La fièvre est en principe une contre-indication, sauf origine non infectieuse.", "Un foyer bactérien à distance du point de ponction est compatible avec l''anesthésie périmédullaire, sous antibiothérapie adaptée.", "Le choc septique contre-indique l''anesthésie périmédullaire, surtout en cas de CIVD ou d''infection intravasculaire [B].", "Chez la femme enceinte fébrile, la péridurale reste possible selon le rapport bénéfice/risque ; chorioamniotite et infection urinaire n''augmentent pas le risque septique.", "Infection par le VIH : anesthésie périmédullaire possible en l''absence de complication opportuniste ou d''atteinte du système nerveux central."]'::jsonb),
  ('blocs_perimedullaires_neuro_2006', '["La migraine, l''épilepsie traitée et équilibrée et les antécédents d''AVC ne contre-indiquent pas l''anesthésie périmédullaire.", "Céphalées récentes ou intenses : éliminer une tumeur ou une hypertension intracrânienne avant le geste.", "Les maladies dégénératives (Alzheimer, Parkinson) ne sont pas des contre-indications ; vérifier que l''état du patient permet la chirurgie sous ce type d''anesthésie.", "Le spina bifida n''est pas une contre-indication [B].", "Toute convulsion après injection d''anesthésique local doit faire rechercher un surdosage."]'::jsonb),
  ('blocs_perimedullaires_postop_2006', '["Lidocaïne et kétamine (avec conservateur) contre-indiquées par voie périmédullaire (neurotoxicité).", "Opioïdes et anesthésiques locaux ont une action synergique ; la morphine procure 10 à 12 h d''analgésie (jusqu''à 24 h).", "Chirurgie abdominale ou thoracique : péridurale associant un anesthésique local faiblement concentré et un morphinique.", "Thoracotomie : la péridurale thoracique est la technique la plus efficace et diminue les complications pulmonaires [A].", "La ropivacaïne est l''anesthésique local de longue durée le moins cardiotoxique."]'::jsonb),
  ('blocs_perimedullaires_technique_2006', '["Seules la ropivacaïne, la bupivacaïne et la lévobupivacaïne ont l''AMM pour l''injection intrathécale ; la lidocaïne est contre-indiquée [A].", "L''extension du bloc est peu prévisible : elle dépend surtout de la dose d''anesthésique local et du volume de LCR.", "Solutions hyperbares : extension dépendante de la position, niveau plus reproductible, régression plus rapide.", "Réduire la dose avec l''âge et en cas de pression intra-abdominale élevée (grossesse, obésité, ascite).", "Faibles doses, injection lente et position latérale ou assise favorisent un bloc unilatéral ou limité."]'::jsonb),
  ('blocs_perimedullaires_terrain_cardioresp_2006', '["Les effets hémodynamiques dépendent de l''étendue du bloc sympathique : limités sous T11, majeurs au-dessus de T6 ou si une anesthésie générale est associée.", "Prévenir et traiter l''hypotension par remplissage et vasoconstricteur (éphédrine ou phényléphrine) ; les colloïdes sont plus efficaces que les cristalloïdes.", "HTA traitée par IEC ou ARA2 : arrêter ces traitements en préopératoire.", "SAOS : risque accru d''intubation difficile et sensibilité aux dépresseurs respiratoires ; les sédatifs amplifient les effets respiratoires du bloc.", "Surveillance par un personnel formé, avec un protocole écrit de surveillance et de traitement des complications [A]."]'::jsonb),
  ('blocs_peripheriques_membres', '["Informer le patient (préférence, risque d''échec et recours à l''anesthésie générale) ; en cas de traitement anticoagulant, évaluer le rapport risque/bénéfice du bloc.", "Monitorage identique à celui d''une anesthésie générale, en place avant le bloc, avec voie veineuse et chariot dédié.", "Sédation légère seulement, le patient restant coopérant et réactif aux stimulations verbales.", "Désinfection cutanée large de type chirurgical [A] ; habillage chirurgical complet pour la pose d''un cathéter.", "Injections lentes et fractionnées, dose-test adrénalinée pour les blocs profonds."]'::jsonb),
  ('bris_dentaires', '["En consultation, rechercher les critères d''intubation et de ventilation au masque difficiles, ainsi que les facteurs de risque dentaires (prothèses, restaurations, mobilité).", "Noter l''état dentaire dans le dossier d''anesthésie, idéalement avec un schéma simplifié, en particulier pour les incisives.", "Informer oralement et par écrit du risque de traumatisme dentaire, et en garder la trace dans le dossier.", "Risque identifié : avis odonto-stomatologique avec panoramique ; pas d''orientation systématique chez le dentiste dans les autres cas.", "En cas de risque identifié, favoriser l''anesthésie locorégionale si le rapport bénéfice/risque le permet."]'::jsonb),
  ('brule_grave', '["Brûlé grave adulte : surface brûlée > 20 %, 3e degré > 5 %, inhalation de fumées, localisation profonde (face, mains, pieds, périnée) ou brûlure électrique haut voltage.", "Évaluer la surface brûlée par la méthode de Lund et Browder.", "Demander sans délai un avis spécialisé et privilégier l''admission directe en centre de traitement des brûlés.", "Perfuser 20 mL/kg de cristalloïde balancé dans la première heure si la surface brûlée est ≥ 20 % (≥ 10 % chez l''enfant), puis adapter le remplissage à l''évaluation hémodynamique.", "Escarrotomie si une brûlure circulaire profonde compromet les voies aériennes, la ventilation ou la circulation."]'::jsonb),
  ('candidoses_aspergilloses', '["Rechercher systématiquement levures et champignons filamenteux chez les patients à risque ; l''examen direct est essentiel et doit être rapide.", "Candida dans les prélèvements respiratoires, lavage broncho-alvéolaire compris, n''a pas de valeur diagnostique.", "Une seule hémoculture positive à Candida suffit au diagnostic de candidose invasive.", "En hématologie, l''antigénémie aspergillaire répétée est sensible, et spécifique si un 2e prélèvement la confirme.", "Aspergillose invasive : voriconazole en première ligne."]'::jsonb),
  ('catheters_veineux_centraux', '["Abandonner la culture qualitative du cathéter, qui ne distingue pas contamination, colonisation et infection.", "Techniques « cathéter en place » possibles seulement sans choc, tunnelite, thrombophlébite ni endocardite, pour éviter les ablations injustifiées.", "Les voies fémorale et probablement jugulaire interne exposent à plus d''infections que la voie sous-clavière chez l''adulte.", "Asepsie chirurgicale à la pose ; limiter les manipulations de la ligne et la durée du cathétérisme.", "Les infections sur cathéter comptent parmi les 3 principales infections acquises en réanimation."]'::jsonb),
  ('chir_ambu_proctologie', '["Privilégier l''ambulatoire quand les conditions médicales et psychosociales sont réunies ; le grand âge et le handicap ne l''interdisent pas.", "Pour limiter la rétention d''urines : restreindre les perfusions IV ; en rachianesthésie, anesthésique local de courte durée et aucun morphinique intrathécal [A].", "Analgésie multimodale avec anesthésiques locaux de longue durée (infiltration périnéale ou bloc pudendal) [A].", "Structure d''urgence accessible en 1 heure au plus ; médecin traitant informé dès la programmation."]'::jsonb),
  ('chir_ambu_urologie_2013', '["Privilégier l''ambulatoire quand les conditions d''éligibilité du patient sont réunies ; enfants et personnes âgées sont de bons candidats.", "Identifier les personnes ressources (accompagnant, aidant, personne de confiance) et vérifier les conditions à chaque étape.", "La consultation de programmation est un temps essentiel d''organisation et d''information.", "Équipe formée à l''ambulatoire et à la réhabilitation précoce ; prévenir les risques de rétention, d''infection, de douleur et d''hémorragie.", "Recommandations reposant presque toutes sur un accord d''experts."]'::jsonb),
  ('choc_hemorragique', '["Tant que le saignement n''est pas contrôlé, limiter le remplissage au maintien des objectifs de pression artérielle ; PAM ≥ 80 mmHg en cas de traumatisme crânien grave associé.", "Cristalloïdes en première intention, pas d''albumine ; noradrénaline si besoin, éventuellement sur voie périphérique dédiée en attendant une voie centrale.", "Acide tranexamique au plus tôt chez le traumatisé : 1 g IV en 10 min puis 1 g sur 8 h [1+].", "Plasma transfusé tôt, idéalement en même temps que les CGR ; plaquettes pour rester au-dessus de 50 G/L.", "Diagnostiquer et traiter sans retard les troubles de l''hémostase ; calcium ionisé > 0,9 mmol/L en cas de transfusion massive."]'::jsonb),
  ('civd', '["La CIVD est une activation systémique et excessive de la coagulation, avec ou sans signes cliniques.", "Terminologie retenue : CIVD biologique, CIVD clinique (hémorragique ou ischémique) et CIVD compliquée.", "Marqueurs : D-dimères élevés, baisse des plaquettes, du taux de prothrombine et du fibrinogène.", "Causes principales : sepsis, traumatismes (crâniens surtout), complications obstétricales, brûlures, pancréatites.", "Stratégie thérapeutique (substitution, traitements spécifiques) définie selon la situation clinique."]'::jsonb),
  ('controle_temperature', '["Coma après arrêt cardiaque extrahospitalier sur rythme choquable : contrôle ciblé de la température [1+], probablement aussi pour un rythme non choquable.", "Viser une température entre 32 et 36 °C après arrêt cardiaque ; pas de solutés froids pendant le transport.", "Traumatisme crânien grave : contrôle ciblé entre 35 et 37 °C pour prévenir l''hypertension intracrânienne.", "Chez l''enfant, viser la normothermie après arrêt cardiaque ; pas d''hypothermie à 32-34 °C après traumatisme crânien grave.", "Utiliser des méthodes asservies à la température corporelle [1+]."]'::jsonb),
  ('coronarien', '["Évaluer le risque sur trois critères : risque de la chirurgie, état cardiaque (score de Lee) et capacité à l''effort [1+].", "Coronarien opéré d''une chirurgie à risque intermédiaire ou élevé : ECG, troponine et hémoglobine répétés pendant 48 h [1+].", "Ne pas refaire un ECG si un bilan cardiologique de moins d''un an est disponible, sans événement intercurrent.", "Échocardiographie de stress ou scintigraphie seulement si le niveau de risque impose un dépistage ; une anomalie étendue fait rediscuter l''indication opératoire.", "Revascularisation préopératoire réservée à des indications restreintes ; décision multidisciplinaire."]'::jsonb),
  ('corticotherapie', '["Choc septique : seules de faibles doses d''hydrocortisone (200 à 300 mg/j) sont bénéfiques.", "Doser la cortisolémie avant de débuter, mais sans retarder le traitement en urgence absolue (purpura fulminans).", "Pas de test au Synacthène systématique : son résultat ne modifie pas la conduite.", "SDRA : pas de corticoïdes à la phase précoce ; méthylprednisolone 2 mg/kg/j seulement en cas de fibroprolifération excessive ou prolongée."]'::jsonb),
  ('curares', '["Administrer un curare pour faciliter l''intubation et réduire les traumatismes pharyngolaryngés [1+], ainsi qu''en chirurgie abdominale [1+].", "Monitorer la curarisation en peropératoire [1+].", "Néostigmine seulement après retour de 4 réponses au train de quatre, à 40-50 µg/kg (masse idéale), puis monitorage jusqu''à un rapport ≥ 0,9.", "Sugammadex dosé selon la masse idéale et la profondeur du bloc induit par le rocuronium.", "Ne pas modifier la dose initiale de curare en cas d''insuffisance rénale ou hépatique."]'::jsonb),
  ('delivrance_information_2012', '["Informer sur l''état de santé, les actes proposés, leurs alternatives, bénéfices, risques fréquents ou graves, et le suivi.", "Information synthétique, hiérarchisée, compréhensible et personnalisée, au cours d''un entretien individuel.", "Vérifier la compréhension (faire reformuler), indiquer la proposition préférée et proposer un second avis si besoin.", "Respecter la volonté de ne pas être informé, sauf si des tiers sont exposés à un risque de transmission.", "Adapter l''information au mineur, au majeur protégé ou à la personne hors d''état de la recevoir."]'::jsonb),
  ('demarches_anticipees_don_organes_2024', '["Démarche anticipée : admission en réanimation d''un patient en coma grave sans perspective thérapeutique, en vue d''un possible prélèvement après mort encéphalique.", "Deux prérequis : décision collégiale de limitation des traitements après avis d''expert, et annonce préalable du pronostic aux proches.", "Donneur possible : lésions cérébrales irréversibles, Glasgow < 8 ou aggravation rapide, sans perspective thérapeutique.", "Appeler la coordination hospitalière des prélèvements, puis mener l''entretien anticipé avec les proches pour recueillir un éventuel refus.", "Procédure locale formalisée (critères d''admission, checklist) et formation des professionnels."]'::jsonb),
  ('diabete_perioperatoire_2025', '["Objectif glycémique périopératoire : 5 à 10 mmol/L (0,9 à 1,8 g/L) ; HbA1c récente (moins de 3 mois) en consultation.", "HbA1c entre 6 et 8 % : intervention possible ; < 5 % ou > 9 % : différer ; entre les deux : avis du médecin traitant ou du diabétologue.", "Diabète de type 1 : ne jamais arrêter l''insuline lente, quelle que soit la glycémie.", "Inhibiteurs de SGLT2 : dernière prise 3 jours avant l''intervention (risque d''acidocétose euglycémique) ; agonistes du GLP-1 non arrêtés, avec échographie gastrique ou induction en séquence rapide.", "Metformine et autres antidiabétiques oraux : pas d''arrêt si un seul repas est sauté ; pas de prise le matin si au moins 2 repas sont sautés."]'::jsonb),
  ('douleur_accouchement_2025', '["Repérage échographique pour la pose chez la patiente obèse ou au rachis difficile [G1] ; interrompre l''HBPM avant la pose.", "Pas de dose-test à la lidocaïne ; bolus initial avec l''anesthésique local du mélange pour détecter un cathéter mal placé [G1].", "Associer systématiquement du sufentanil aux anesthésiques locaux en péridurale ; pas de clonidine en première intention [G1].", "En cas d''insuffisance : mesures correctrices évaluées en 30 à 45 min, nouvelle pose du cathéter si échec à 45 min [G1].", "L''analgésie périmédullaire est préférable aux opioïdes en PCA ; sous opioïdes, surveillance rapprochée clinique et SpO2/CO2 [G1]."]'::jsonb),
  ('douleur_postoperatoire', '["Évaluer la douleur par autoévaluation chiffrée avant l''intervention, en SSPI puis régulièrement, avec la sédation et la ventilation, et la tracer.", "Pas de prescription « à la demande » : doses de secours sur critères fiables (score de douleur).", "Protocoles écrits utilisant les techniques efficaces (ACP morphinique, analgésie multimodale, ALR), avec prévention des effets secondaires.", "Informer le patient oralement et par écrit, avant et après l''intervention.", "Démarche institutionnelle avec référents, notamment infirmiers référents douleur, et évaluation continue de la qualité."]'::jsonb),
  ('douleur_reactualisation_2016', '["Chez l''enfant : autoévaluation (échelle des visages) dès 5 ans, sinon échelle FLACC avant 7 ans [1+].", "Associer un AINS ou un anti-COX2 à la morphine en l''absence de contre-indication [1+].", "Douleur sévère : opiacé fort (morphine ou oxycodone), de préférence par voie orale, quel que soit l''âge [1+].", "Kétamine à faible dose en peropératoire pour les chirurgies très douloureuses ou à risque de douleur chronique, et chez les patients sous opioïdes au long cours [1+].", "Rester sous les doses toxiques d''anesthésiques locaux, surtout quand infiltrations et cathéters périnerveux sont associés [1+]."]'::jsonb),
  ('ecbu', '["L''ECBU est la référence pour dépister une colonisation urinaire ; ne pas utiliser la bandelette urinaire.", "ECBU préopératoire seulement pour certains actes (RTUP, NLPC, urétéroscopie notamment), dans les 10 jours précédant l''intervention.", "Pas d''ECBU indiqué : ne pas traiter une colonisation, même avec du matériel endo-urinaire en place.", "Seule la culture compte : ni le Gram ni la leucocyturie ne préjugent du résultat.", "Infection urinaire (et non simple colonisation) : reporter l''intervention jusqu''à sa résolution."]'::jsonb),
  ('echo_acces_vasculaires', '["Échoguidage recommandé pour la pose d''un cathéter jugulaire interne, sous-clavier ou fémoral chez l''adulte [1+].", "Chez l''enfant, échoguidage recommandé pour les voies jugulaire interne et fémorale [1+] ; pas de recommandation pour la voie sous-clavière.", "Échoguidage probablement recommandé pour l''artère radiale et la veine périphérique difficile [2+].", "Pour la jugulaire interne, l''échoguidage réduit les échecs de 86 % et les ponctions artérielles de 80 %."]'::jsonb),
  ('echo_alr', '["Maîtriser les bases physiques des ultrasons, les réglages de l''échographe et la sonoanatomie ; s''entraîner sur mannequin ou fantôme.", "Choisir une sonde adaptée au bloc et la fréquence la plus élevée possible ; utiliser des aiguilles dédiées à l''ALR.", "Visualiser largement les structures avant le geste, puis suivre en continu l''extrémité de l''aiguille et la diffusion de l''anesthésique local.", "Arrêter l''injection si la diffusion n''est pas visible, ou en cas de douleur, paresthésie, résistance ou gonflement du nerf.", "En cas de mauvaise visualisation, associer la neurostimulation à l''échoguidage."]'::jsonb),
  ('eclsa', '["L''arrêt cardiaque réfractaire se définit par l''absence de reprise d''activité circulatoire après au moins 30 minutes de RCP médicalisée en normothermie.", "L''assistance circulatoire (ECLS) est une indication potentielle et non une obligation : son bénéfice n''est pas établi et elle n''est pas disponible partout.", "La décision repose sur les durées de no-flow et de low-flow, la valeur de l''ETCO2 et les éléments qui modulent le pronostic (hypothermie, signes de vie).", "Les bases de la RCP usuelle restent inchangées pour la plupart des arrêts cardiaques non réfractaires."]'::jsonb),
  ('eeg_cortical', '["L''EEG cortical (BIS®, Entropie®) explore surtout la composante hypnotique de l''anesthésie, pas l''ensemble de ses effets.", "Les moniteurs ne sont pas interchangeables : les résultats d''un appareil ne s''extrapolent pas à un autre.", "Le monitorage permet de réduire de 10 à 40 % les doses d''hypnotiques et dépiste en partie le risque de mémorisation.", "Chez l''enfant, le BIS est utilisable après 2 ans en anesthésie intraveineuse ; pas de données avant 2 ans."]'::jsonb),
  ('eer', '["Démarrer l''épuration extrarénale sans délai en cas de menace vitale : hyperkaliémie, acidose métabolique, syndrome de lyse, œdème pulmonaire réfractaire.", "Hors urgence vitale, les données ne permettent pas de fixer le délai optimal de démarrage.", "Éviter la voie sous-clavière ; fémorale et jugulaire interne droite sont équivalentes (jugulaire préférée si IMC > 28 kg/m²), avec échoguidage.", "En fémoral, cathéter de plus de 12 F et d''au moins 24 cm ; chez l''enfant, adapter le calibre au poids.", "Retirer le cathéter dès qu''il n''est plus nécessaire."]'::jsonb),
  ('epanchement_pleural', '["Préférer l''échographie pleuropulmonaire à la radiographie pour diagnostiquer un épanchement en soins critiques.", "Analyse biochimique, cytologique et bactériologique du liquide à la première ponction, puis si la cause peut avoir changé.", "Poser l''indication de ponction ou de drainage sur le volume, la rapidité d''installation et la tolérance respiratoire, pas sur l''imagerie seule.", "Échorepérage au minimum, échoguidage au mieux, pour la pose du drain.", "Recommandations d''experts, hors pleurésie purulente, hémothorax et épanchement néoplasique."]'::jsonb),
  ('erreurs_medicamenteuses', '["Une erreur médicamenteuse survient dans 1 anesthésie sur 900 à 1 sur 130.", "Les erreurs portent surtout sur les seringues et ampoules (50 %), avec en tête la confusion de spécialité.", "Prévenir les erreurs de reconstitution : contrôle de la spécialité, dilution standardisée, étiquetage systématique.", "Étiqueter les seringues selon le code couleur international par classe (curares en rouge, opioïdes en bleu, anesthésiques locaux en gris)."]'::jsonb),
  ('erreurs_medicamenteuses_2024', '["Standardiser par des protocoles la prescription, la préparation et l''administration (dilution, solvant, durée, vitesse, voie).", "Utiliser en soins critiques un logiciel de prescription avec aide à la décision, paramétré pour la population prise en charge.", "Bilan et conciliation médicamenteuse en anesthésie et en soins critiques.", "Proscrire plusieurs concentrations d''un même médicament dans le plateau ; double contrôle à l''administration.", "29 avis d''experts, qui actualisent les préconisations SFAR/SFPC de 2016."]'::jsonb),
  ('erreurs_medicamenteuses_ar_2016', '["Chaque structure met en place des mesures écrites de prévention et un retour d''expérience (REMED, ALARM, RMM).", "Une équipe pluriprofessionnelle dédiée analyse les risques a priori et a posteriori, avec un pharmacien.", "Conciliation médicamenteuse dès la consultation d''anesthésie ; attention aux médicaments à haut risque.", "Étiquetage au code couleur international, règle des 5B, détrompeurs et lecteurs de code-barres.", "Formation continue, de préférence par simulation (chambre des erreurs). Actualisé en 2024."]'::jsonb),
  ('examens_pertinence_rea', '["Discuter les examens biologiques à chaque évaluation clinique pour en limiter le nombre [1+].", "Hémocultures devant tout sepsis, par ponction veineuse, 40 à 60 mL répartis en 4 à 6 flacons [1+].", "Prélèvements pulmonaires seulement en cas de suspicion de pneumonie nosocomiale, sans les répéter si l''évolution est favorable.", "Pas de dépistage systématique des colonisations urinaires, sauf grossesse ou chirurgie des voies urinaires.", "Risque cardiaque postopératoire : troponine systématique du jour de l''intervention au 3e jour."]'::jsonb),
  ('examens_preinterventionnels', '["Évaluer le risque hémorragique par l''interrogatoire et l''examen ; avis spécialisé en cas d''anamnèse évocatrice [1+].", "Hémogramme avant toute intervention à risque intermédiaire ou élevé [1+].", "Groupage et RAI si le risque transfusionnel ou hémorragique est intermédiaire ou élevé, résultats disponibles avant l''intervention.", "RAI négative valable 21 jours (au lieu de 3) en l''absence de circonstance immunisante dans les 6 mois.", "Rechercher une grossesse possible chez toute femme en âge de procréer (bHCG plasmatiques si doute) ; ECBU systématique avant chirurgie urologique."]'::jsonb),
  ('facteurs_humains_2022', '["Briefing avant une situation critique et débriefing juste après.", "Communication sécurisée et standardisée en situation de crise.", "Un leader clairement identifié, des informations partagées et une répartition cohérente des tâches.", "Utiliser des aides cognitives de crise.", "Matériel d''urgence rangé logiquement, à un emplacement connu de tous et vérifié ; formation avant tout nouveau matériel."]'::jsonb),
  ('gestion_traitements_chroniques_cardio_2009', '["Bêtabloquants et statines : ne pas les interrompre en périopératoire ; bêtabloquant le matin de l''intervention.", "IEC et sartans prescrits pour une HTA : les arrêter au moins 12 h avant ; les maintenir en cas d''insuffisance cardiaque.", "Diurétiques : pas de prise le matin de l''intervention.", "Ne pas interrompre nicorandil ni dérivés nitrés oraux ; amiodarone poursuivie jusqu''au matin de l''intervention.", "Ne jamais arrêter brutalement le sotalol."]'::jsonb),
  ('gestion_traitements_chroniques_douleur_toxico_2009', '["Donner la dose habituelle de morphinique avant l''intervention (ou une dose équianalgésique) ; ne pas retirer un patch de fentanyl.", "Poursuivre les antalgiques de palier 2 et les traitements à visée antalgique (antiépileptiques, antidépresseurs, benzodiazépines).", "Ne pas interrompre les pompes intrathécales (opiacés, baclofène), pour éviter un sevrage.", "Traitement de substitution aux opiacés : dose quotidienne le matin de l''intervention, poursuivie pendant tout le séjour ; privilégier l''ALR.", "Stimulateur médullaire : pas d''anesthésie ni d''analgésie périmédullaire."]'::jsonb),
  ('gestion_traitements_chroniques_infectieux_2009', '["Poursuivre les antituberculeux aux mêmes doses, avec la supplémentation en vitamines B1 et B6.", "Antirétroviraux : éviter tout arrêt ; si inévitable, moins de 48 h et arrêt puis reprise simultanés de toutes les molécules, après avis spécialisé.", "Ciclosporine et tacrolimus : surveiller taux plasmatiques et fonction rénale avec le spécialiste, et reprendre tôt.", "Azathioprine, mycophénolate et cyclophosphamide : administrés avec la prémédication.", "Méthotrexate et thalidomide : ne pas interrompre, en surveillant leur toxicité."]'::jsonb),
  ('gestion_traitements_chroniques_neuro_psy_2011', '["Ne pas arrêter le traitement antiparkinsonien, ni un stimulateur cérébral profond.", "Prévoir une substitution si la voie orale est impossible (lévodopa dispersible par sonde, apomorphine sous-cutanée).", "Antidépresseurs maintenus jusqu''au matin de l''intervention et repris tôt : l''arrêt brutal expose à une rechute et à un syndrome de sevrage.", "Imipraminiques : à interrompre en cas de pathologie cardiovasculaire.", "IMAO : moclobémide maintenu ; iproniazide maintenu après discussion pluridisciplinaire, ou arrêté au moins 2 semaines avant."]'::jsonb),
  ('glycemie', '["Hypoglycémie sévère en réanimation : glycémie < 2,2 mmol/L (0,4 g/L) ; elle peut causer des lésions cérébrales irréversibles.", "Le contrôle glycémique strict augmente le risque d''hypoglycémies sévères et impose une surveillance rapprochée.", "Ne pas se fier aux signes cliniques seuls pour dépister l''hypoglycémie chez un patient qui ne peut pas s''exprimer.", "Préférer les prélèvements artériels ou veineux au capillaire, qui surestime souvent la glycémie.", "Éviter les variations glycémiques importantes ; pas de contrôle strict en urgence."]'::jsonb),
  ('hospit_ambulatoire', '["Privilégier l''ambulatoire dès que ses conditions sont réunies ; éligibilité fondée sur le triptyque acte-patient-structure.", "Patients ASA I, II et III stable éligibles au cas par cas.", "Retour accompagné par un tiers, sans conduire ; la distance du domicile n''est pas un critère d''exclusion.", "Information précoce et répétée à chaque étape, concertée entre les intervenants.", "Convention avec un autre établissement pour prendre en charge une complication éventuelle."]'::jsonb),
  ('hsa', '["Céphalée brutale, intense et inhabituelle : scanner cérébral en urgence devant toute suspicion d''hémorragie sous-arachnoïdienne.", "HSA grave : grades III à V de la classification WFNS, à préférer à celle de Hunt et Hess.", "Suivre la gravité avec le score de Glasgow tout au long de l''évolution.", "Prévention du vasospasme : nimodipine orale 360 mg/j pendant 21 jours [A].", "Traiter l''anévrisme (chirurgie ou voie endovasculaire) dans les 72 premières heures, en centre de référence."]'::jsonb),
  ('hyperthermie_maligne', '["Dépister les patients à risque en consultation d''anesthésie (myopathies liées à RYR1, CPK élevées inexpliquées, hyperthermie ou rhabdomyolyse graves d''effort).", "Antécédent personnel ou familial non exploré : contacter un centre expert avant une chirurgie programmée.", "En urgence, chez un patient à risque : précautions anesthésiques d''emblée (pas d''halogénés ni de succinylcholine).", "Un antécédent de syndrome malin des neuroleptiques n''est pas une situation à risque.", "Crise : appliquer le protocole de traitement, avec le dantrolène."]'::jsonb),
  ('hypothermie', '["Lutter contre l''hypothermie pour réduire les complications infectieuses, cardiovasculaires et hémorragiques [1+].", "Maintenir une température centrale ≥ 36,5 °C.", "Réchauffement cutané actif [1+], débuté avant l''induction (pré-warming) et préféré à l''isolation passive.", "Réchauffer les solutés IV en cas de grands volumes, et les produits sanguins, avec un matériel dédié, en plus du réchauffement cutané [1+]."]'::jsonb),
  ('ih', '["Insuffisance hépatique aiguë sévère : paracétamolémie, sérologies virales A et B, toxiques urinaires, échographie cardiaque et écho-Doppler hépatique [1+].", "Suspicion d''intoxication au paracétamol : N-acétylcystéine sans attendre la paracétamolémie [1+].", "Contacter un centre de transplantation hépatique en cas d''insuffisance hépatique aiguë sévère.", "Cirrhotique : albumine en cas de paracentèse de plus de 4 à 5 litres [1+].", "Hémorragie digestive du cirrhotique : vasoactif IV et antibiothérapie au plus tôt, endoscopie rapide, hémoglobine cible entre 7 et 8 g/dL [1+]."]'::jsonb),
  ('impact_environnemental_ag', '["À bénéfice égal, préférer le sévoflurane au desflurane et à l''isoflurane, et ne pas utiliser le protoxyde d''azote.", "Bas débit de gaz frais, avec monitorage de la profondeur d''anesthésie pour réduire la consommation d''halogénés ou de propofol.", "Préparer les médicaments au moment du besoin et préférer les seringues préremplies pour les drogues d''urgence.", "Privilégier les dispositifs médicaux réutilisables."]'::jsonb),
  ('infarctus_myocarde', '["La décision de désobstruction repose sur la probabilité clinique, l''ECG puis la troponine.", "Forte probabilité clinique avec ECG contributif : désobstruction coronaire urgente.", "Aspirine dans tout SCA ; clopidogrel à la phase précoce d''un SCA ST+ [A].", "Corriger l''hyperglycémie par l''insuline ; la solution glucose-insuline-potassium n''est pas recommandée.", "Organisation par le SAMU-Centre 15 pour réduire les délais de reperfusion."]'::jsonb),
  ('infections_intra_abdominales', '["Choc septique ou immunodépression : hémocultures et recherche de levures dans le liquide péritonéal [1+].", "Protocoles probabilistes fondés sur les données locales et nationales de résistance [1+].", "Pas de clindamycine ni de céfoxitine en probabiliste (résistance des bactéroïdes).", "Pas de traitement antifongique probabiliste sans signe de gravité.", "Infection associée aux soins : risque élevé de BMR si antibiothérapie récente ou reprise chirurgicale tardive."]'::jsonb),
  ('infections_intra_abdominales_2026', '["Infection communautaire sans sepsis : C3G (céfotaxime ou ceftriaxone) + métronidazole, sans viser les BLSE.", "Choc septique communautaire sans facteur de risque de BLSE : pipéracilline-tazobactam.", "Infection associée aux soins sans facteur de risque de BMR : céfépime + métronidazole [1+] ; carbapénème si au moins 2 critères de BMR (un seul en cas de sepsis).", "Sepsis ou choc septique : admission en soins critiques [1+].", "Source contrôlée : 2 jours d''antibiotiques après appendicite compliquée, 4 jours pour les autres infections communautaires [1+]."]'::jsonb),
  ('infections_nosocomiales_rea', '["Surveiller les infections nosocomiales du service avec des définitions standardisées.", "Désescalade antibiotique, avec réévaluation systématique entre H24 et H72.", "Pneumopathie acquise sous ventilation : 8 jours d''antibiotiques au lieu de 15, sauf bacilles Gram négatif non fermentants.", "Algorithme de sédation-analgésie pour raccourcir la ventilation, et prévention des extubations non programmées.", "Chambres individuelles d''au moins 20 m² ; eau stérile pour les soins à risque."]'::jsonb),
  ('insuffisance_analgesie_cesarienne', '["Insuffisance ou échec d''analgésie : toute anesthésie périmédullaire conduisant à un complément souhaité par la patiente ; son confort compte autant que le niveau du bloc.", "Avant l''incision : niveau sensitif bilatéral et symétrique en T6 au toucher (éventuellement T3 au froid).", "Test de pincement par l''obstétricien au niveau de l''incision, systématique, même en urgence.", "Rachianesthésie : plus de 10 mg de bupivacaïne hyperbare limiterait le risque d''échec ; la rachi-péridurale combinée permet un complément.", "Une péridurale imparfaite pendant le travail expose à l''échec de sa conversion pour une césarienne."]'::jsonb),
  ('intubation_difficile_adulte', '["Préoxygénation systématique (3 min ou 8 inspirations profondes), y compris en urgence [1+].", "Chirurgie programmée avec au moins 2 critères d''intubation difficile et ventilation au masque possible : vidéolaryngoscope en première intention [1+].", "Maintenir une anesthésie profonde avec des agents rapidement réversibles pour optimiser ventilation au masque et intubation [1+].", "S''appuyer sur des arbres décisionnels pour gérer un contrôle difficile des voies aériennes [1+].", "Anticiper les extubations à risque à partir de critères identifiés."]'::jsonb),
  ('intubation_reanimation', '["Considérer tout patient de réanimation à risque d''intubation compliquée, et préparer la procédure (oxygénation, hémodynamique) [1+].", "Confirmer la position de la sonde par capnographie ; chariot d''intubation difficile et bronchoscope disponibles [1+].", "Si la succinylcholine est contre-indiquée : rocuronium à plus de 0,9 mg/kg (1 à 1,2 mg/kg), avec accès rapide au sugammadex [1+].", "Épreuve de ventilation spontanée avant toute extubation après plus de 48 h de ventilation [1+].", "Test de fuite en cas de facteur de risque de dyspnée laryngée ; corticoïdes au moins 6 h avant l''extubation s''ils sont décidés."]'::jsonb),
  ('intubation_urgence', '["Préoxygénation systématique, par VNI en l''absence de contre-indication [1+].", "À l''hôpital, vidéolaryngoscope en première intention [1+].", "Capnographie systématique pour confirmer la position de la sonde [1+].", "Traumatisme crânien grave : intubation, en maintenant la PAS au-dessus de 110 mmHg et l''EtCO2 entre 35 et 45 mmHg.", "Pas d''intubation sur la seule indication d''un choc hémorragique ; obstruction des voies aériennes : prioriser leur libération et l''oxygénation."]'::jsonb),
  ('ira', '["IRA selon KDIGO : créatinine +26,5 µmol/L en 48 h, ou ≥ 1,5 fois la valeur de base en 7 jours, ou diurèse < 0,5 mL/kg/h pendant 6 h.", "Ne pas utiliser les formules estimées du DFG (Cockcroft, MDRD, CKD-EPI) en réanimation ou en postopératoire.", "Maintenir une PAM minimale entre 60 et 70 mmHg pour prévenir et traiter l''IRA [1+].", "Guider le remplissage périopératoire par le monitorage du volume d''éjection systolique [1+].", "Après une IRA, considérer le patient à risque d''insuffisance rénale chronique [1+]."]'::jsonb),
  ('ivg_14sa', '["Consultation obtenue dans les 5 jours suivant l''appel : une IVG précoce réduit les complications.", "Au-delà de 12 SA, prise en charge dans une structure disposant d''un plateau technique chirurgical.", "Préparation cervicale par mifépristone 200 mg 36 à 48 h avant, ou misoprostol 400 µg 3 à 4 h avant l''aspiration [A].", "L''ibuprofène diminue la douleur per- et postopératoire [A].", "Information claire sur les méthodes et l''anesthésie ; entretien psychosocial proposé systématiquement ; prévention infectieuse et rhésus."]'::jsonb),
  ('lat_soins_critiques', '["Réunions pluriprofessionnelles régulières sur le projet de soins, et recherche précoce des volontés du patient.", "Protocole de service d''aide à la décision ; participation active des paramédicaux à la procédure collégiale.", "Après décision d''arrêt des traitements : sédation profonde et continue jusqu''au décès (objectif RASS -5), avec analgésie.", "Accompagnement structuré des proches après la décision [1+]."]'::jsonb),
  ('mal_epileptique', '["État de mal : crises continues ou successives sans retour à la conscience pendant 30 minutes.", "Pour l''état de mal tonicoclonique généralisé, prise en charge dès 5 minutes de crises continues ou subintrantes.", "L''état de mal larvé (coma, signes moteurs atténués, EEG persistant) complique un état de mal mal traité.", "Les formes non convulsives nécessitent un EEG ; évoquer un pseudo-état de mal devant des manifestations atypiques.", "Réévaluation neurologique à distance de tout état de mal."]'::jsonb),
  ('mieux_vivre_reanimation', '["Réduire le bruit (alarmes souvent > 80 dB) et respecter l''alternance jour/nuit avec de la lumière naturelle.", "Chambre individuelle, intimité, heure et date visibles pour le patient.", "Contention physique seulement si la sécurité est en jeu, prescrite chaque jour et minimale.", "Le delirium touche un patient sur trois ; prévenir douleur et privation de sommeil.", "Communication structurée avec les familles (livret d''accueil, entretiens suffisants) et prévention de l''épuisement des soignants."]'::jsonb),
  ('monitorage_traumatise', '["Le monitorage complète l''examen clinique, souvent pris en défaut : 20 % des décès traumatiques sont évitables.", "Oxymétrie de pouls systématique et capnographie après intubation.", "Surveillance ECG continue ; brassard adapté, en sachant que la mesure oscillométrique n''est pas fiable en cas d''hypotension ou de frissons.", "Hémoglobinomètre (Hémocue®) préférable à l''hématocrite par microméthode [A].", "Chez l''enfant : fréquence cardiaque, PA non invasive, SpO2 et capnographie avec du matériel adapté [A]."]'::jsonb),
  ('mort_encephalique', '["Diagnostic clinique : coma non réactif (Glasgow 3), abolition des réflexes du tronc et de la ventilation spontanée, après élimination des facteurs confondants (température < 35 °C, toxiques).", "Épreuve d''hypercapnie : PaCO2 proche de 60 mmHg en apnée, sous oxygénation contrôlée.", "Confirmation légale exigée : deux EEG nuls et non réactifs à 4 h d''intervalle, ou angiographie montrant l''arrêt de perfusion des 4 axes.", "Le Doppler transcrânien n''a pas de valeur réglementaire mais oriente rapidement vers l''arrêt circulatoire cérébral.", "Réanimer le donneur potentiel (hémodynamique, diabète insipide) avec la coordination hospitalière."]'::jsonb),
  ('mtev_perioperatoire', '["Mettre en place des protocoles locaux de thromboprophylaxie, avec déambulation précoce.", "Après prothèse de hanche ou de genou : thromboprophylaxie de 35 jours (hanche) ou 14 jours (genou) [1+] ; schéma séquentiel avec aspirine possible dans un parcours RAAC sans facteur de risque majeur.", "Chirurgie abdominopelvienne à risque élevé : HBPM pendant 4 semaines, même en mini-invasif [1+].", "Anticoagulants contre-indiqués : compression pneumatique intermittente [1+].", "Adapter la thromboprophylaxie à la fonction rénale ; retirer le filtre cave dès la reprise de l''anticoagulation curative."]'::jsonb),
  ('nutrition', '["Tout patient de réanimation hospitalisé plus de 3 jours est à risque de dénutrition.", "Nutrition entérale dans les 24 h si le patient est dénutri ou ne peut s''alimenter dans les 3 jours ; préférer l''entérale à la parentérale.", "Parentérale de complément si la cible calorique n''est pas atteinte au plus tard après 1 semaine.", "Apport protéique de 1,2 à 1,5 g/kg/j ; position semi-assise > 30° pendant la nutrition entérale.", "Prokinétiques (métoclopramide, érythromycine) en cas de trouble de la vidange gastrique."]'::jsonb),
  ('nutrition_clinique_2026', '["Rechercher une dénutrition (critères HAS) avant une chirurgie à risque intermédiaire ou élevé et chez tout patient de soins critiques [1+].", "Reprendre au plus tôt une nutrition orale ou artificielle après la chirurgie [1+].", "État de choc : cible énergétique basse ; voie entérale ou parentérale indifférente [1+].", "Patient stabilisé : pas plus de 20 kcal/kg/j ni de 0,9 g/kg/j de protéines [1+].", "Intolérance digestive haute : érythromycine ou métoclopramide pendant 48 à 72 h [1+]."]'::jsonb),
  ('nutrition_perioperatoire', '["Rechercher les facteurs de risque de dénutrition et évaluer l''état nutritionnel (poids, perte de poids, IMC) avant la chirurgie.", "Noter le grade nutritionnel (GN1 à GN4) dans le compte rendu de consultation d''anesthésie.", "GN4 : assistance nutritionnelle préopératoire d''au moins 7 à 10 jours, entérale si le tube digestif est fonctionnel.", "Jeûne préopératoire limité à 2-3 h pour les liquides clairs et 6 h pour un repas léger.", "Reprendre l''alimentation orale dans les 24 premières heures selon la tolérance."]'::jsonb),
  ('nvpo', '["Estimer le risque de NVPO avec un score simplifié (Apfel) [1+].", "Prophylaxie chez les patients à risque : sétron en fin d''intervention, dexaméthasone 4 à 8 mg à l''induction, dropéridol [1+].", "Risque modéré ou élevé : associer au moins deux antiémétiques ; approche multimodale si risque élevé.", "Traitement curatif sans prophylaxie préalable : sétron en première intention.", "Utiliser un algorithme adapté aux contraintes locales ; compenser le jeûne par un apport hydrique suffisant."]'::jsonb),
  ('optimisation_beta_lactamines_2018', '["Viser une concentration libre de 4 à 8 fois la CMI pendant 100 % de l''intervalle de dose ; au-delà de 8 fois, aucun bénéfice et un risque toxique.", "À l''initiation, posologie journalière plus élevée qu''hors soins critiques, surtout chez les patients graves à fonction rénale conservée.", "Perfusion prolongée ou continue en cas de CMI élevée, de choc ou de score de gravité élevé.", "Estimer le DFG par la clairance de la créatinine (UxV/P) et doser l''albuminémie au début du traitement.", "Suivi thérapeutique pharmacologique, notamment sous épuration extrarénale."]'::jsonb),
  ('optimisation_hemodynamique_adulte_2024', '["Éviter une PAM peropératoire < 60-70 mmHg ; chez l''hypertendu chronique, viser > 90 % de la valeur habituelle ou > 70 mmHg.", "Patient à risque élevé : monitorer le volume d''éjection systolique (Doppler œsophagien ou analyse de la courbe de pression), avec un indice dynamique.", "Césarienne sous rachianesthésie : pas d''éphédrine en prophylaxie ; phényléphrine ou noradrénaline faiblement concentrée [G1].", "Césarienne : maintenir la PAS entre 90 et 100 % de sa valeur de base ; traiter sans délai si elle passe sous 80 %.", "Cristalloïdes balancés ; noradrénaline préférée à la phényléphrine ; dobutamine si un inotrope est nécessaire."]'::jsonb),
  ('optimisation_hemodynamique_pediatrie_2024', '["PAM peropératoire à maintenir : > 35 mmHg avant 6 mois, > 43 mmHg de 6 mois à 2 ans, > 1,5 × âge + 40 mmHg de 2 à 10 ans.", "Doppler œsophagien chez l''enfant à risque élevé, si la tête est accessible et sans échocardiographie peropératoire.", "Lactatémie utile en cas de suspicion d''hypoxie tissulaire.", "Cristalloïde balancé en première intention ; albumine à 4-5 % chez le nouveau-né et le nourrisson ; vasoconstricteur si l''hypotension persiste."]'::jsonb),
  ('organisation_anesthesie_pediatrique_2023', '["Anesthésie dans une salle équipée d''un matériel adapté au poids et à l''âge ; chariot pédiatrique mobile dans les salles non dédiées.", "Secteur pédiatrique en SSPI et hospitalisation dans un secteur dédié, avec un accompagnant.", "Matériel d''abord intraosseux disponible dans tous les lieux d''anesthésie pédiatrique.", "Orienter vers un centre spécialisé : nouveau-né de moins de 6 semaines, ancien prématuré de moins de 60 semaines post-conception, ASA 3 à 5.", "Solutés peropératoires adaptés à l''âge (glucosés chez le nouveau-né et le nourrisson, balancés après 3 ans)."]'::jsonb),
  ('organisation_ar_obstetricale', '["Accès permanent à une salle d''intervention dédiée à l''urgence obstétricale, contiguë au secteur de naissance.", "Anesthésiste-réanimateur disponible dans des délais compatibles avec la sécurité, avec un personnel d''assistance identifié chaque jour.", "Au-delà de 2000 accouchements par an, anesthésiste-réanimateur dédié au secteur de naissance.", "Organisation opérationnelle 24 h/24 ; ressources réévaluées au moins tous les 2 ans.", "Consultation préanesthésique obligatoire, avec stratégie analgésique et information de la patiente."]'::jsonb),
  ('organisation_usc_2018', '["L''USC accueille des patients à risque de défaillance vitale, sur un critère de sécurité médicale et non de tarification.", "Elle n''assure pas de suppléance d''organe (hors préparation d''un transfert) ni de processus de fin de vie.", "Avec une réanimation sur site, l''USC est placée sous la même autorité médicale et paramédicale.", "Au moins 6 lits ; personnel paramédical (IDE + AS) ≥ 0,4 par lit ouvert ; présence médicale 24 h/24.", "Formation spécifique d''adaptation à l''emploi pour les paramédicaux."]'::jsonb),
  ('pancreatite', '["Admission en soins critiques en cas de défaillance d''organe ou de risque de le devenir ; aucun score isolé ne suffit à la décision.", "Scanner abdomino-pelvien précoce en cas de doute diagnostique ou d''aggravation ; bilan étiologique rapide (bilan hépatique, triglycérides, calcémie, échographie).", "Patient ventilé : surveiller la pression intra-abdominale [1+].", "Nutrition entérale plutôt que parentérale exclusive [1+].", "CPRE en urgence seulement en cas d''angiocholite ; drainage de la nécrose infectée par une approche graduée mini-invasive."]'::jsonb),
  ('pavm', '["Approche standardisée et multimodale de prévention des pneumonies associées aux soins [1+].", "Limiter sédation et analgésie, favoriser la VNI (notamment chez le BPCO) et la nutrition entérale précoce.", "Décontamination digestive sélective possible si la prévalence des BMR est faible (< 20 %).", "Ne pas utiliser les scores cliniques (CPIS) pour le diagnostic.", "Monothérapie probabiliste chez l''immunocompétent sans facteur de risque de BMR ni critère de gravité [1+]."]'::jsonb),
  ('plyo_transfusion', '["Hémorragie sans urgence vitale : préférer le plasma frais congelé.", "Transfusion massive à l''hôpital : débuter immédiatement 2 à 4 PLYO avec un ratio plasma/CGR ≥ 1:2, en attendant le plasma décongelé.", "En préhospitalier : 2 à 4 PLYO seulement si un protocole de transfusion massive est activé et si le transport dure plus de 20 min.", "Chez l''enfant : 10 à 15 mL/kg de PLYO dans les mêmes indications."]'::jsonb),
  ('ponction_lombaire', '["Contre-indications formelles : hypertension intracrânienne, infection au point de ponction, thrombopénie sévère et troubles de l''hémostase.", "Un examen neurologique normal et minutieux permet de se passer d''imagerie avant la ponction.", "Aiguille atraumatique de calibre ≤ 22G avec introducteur, et asepsie rigoureuse.", "Le syndrome post-PL (céphalée orthostatique) est l''effet indésirable le plus fréquent ; rechercher les signes d''alerte d''une complication grave.", "Céphalée post-PL persistante : blood-patch."]'::jsonb),
  ('preeclampsie', '["Pré-éclampsie sévère : traiter toute PAS ≥ 160 et/ou PAD ≥ 110 mmHg persistant plus de 15 min, et rester sous ces seuils [1+].", "Voie intraveineuse si signe de gravité ou HTA persistante malgré un traitement oral [1+].", "Sulfate de magnésium en cas de signe clinique de gravité, et en première intention après une éclampsie [1+].", "Entre 24 et 34 SA sans signe de gravité surajouté : poursuivre la grossesse jusqu''à 34 SA [1+].", "Pré-éclampsie sévère : HTA sévère, protéinurie > 3 g/24 h, oligurie, thrombopénie < 100 000/mm³, cytolyse ou douleur épigastrique."]'::jsonb),
  ('preparation_colique', '["Coloscopie le matin : prise fractionnée de la préparation ; l''après-midi, prise complète le matin même possible.", "Délai optimal de 3 à 5 h entre la fin de la purge et la coloscopie.", "Les liquides de préparation se comportent comme des liquides clairs : un délai de 3 h avant l''induction est sûr sans retard de vidange gastrique.", "Adapter le délai en cas de vidange gastrique retardée (opiacés, diabète ancien, Parkinson, douleur aiguë…).", "Phosphate de sodium contre-indiqué avant 18 ans et après 65 ans."]'::jsonb),
  ('programme_optimisation_perioperatoire_2022', '["Inclure tous les patients, y compris âgés ou fragiles, dans un programme d''optimisation périopératoire [1+].", "Jeûne limité à 6 h pour les solides, liquides clairs jusqu''à 2 h avant la chirurgie [1+].", "Ventilation protectrice : 6 à 8 mL/kg de poids idéal, PEP ≥ 5 cmH2O, recrutements itératifs [1+].", "ALR pour la chirurgie des membres et la chirurgie majeure ouverte ; prévention de l''hypothermie et des NVPO [1+].", "Dexaméthasone 4 ou 8 mg à chaque anesthésie générale ; acide tranexamique en chirurgie à risque hémorragique [1+]."]'::jsonb),
  ('protection_oculaire', '["Anesthésie générale : occlusion palpébrale systématique par bandes adhésives, dès la perte du réflexe ciliaire et avant l''intubation.", "Vérifier régulièrement que l''occlusion est complète.", "Chirurgies à risque (tête et cou, décubitus ventral ou latéral) : ajouter un lubrifiant aqueux sans conservateur ; pas de pommade grasse.", "En réanimation, dépister les lésions cornéennes à la fluorescéine chez les patients sédatés ou à faible niveau de conscience.", "Formation des équipes et protocole de prévention dans chaque structure."]'::jsonb),
  ('raac_cardiaque_2021', '["Sevrage tabagique le plus tôt possible avant chirurgie cardiaque [1+].", "Décolonisation nasale de S. aureus par mupirocine sans dépistage préalable, avec bain de bouche [1+].", "Prévenir la fibrillation atriale postopératoire [1+] ; corriger une anémie ferriprive dans un programme de gestion du capital sanguin [1+].", "CEC en normothermie et « CEC optimisée » [1+].", "Extubation dans les 6 h suivant la fin de la chirurgie [1+]."]'::jsonb),
  ('raac_colorectal', '["Pas de préparation colique systématique en chirurgie colique.", "Boisson riche en carbohydrates avant l''intervention chez les patients ASA 1 ou 2 ; jeûne de 2 h pour les liquides clairs.", "Laparoscopie, optimisation hémodynamique des apports, prévention de l''hypothermie et des NVPO [1+].", "Analgésie multimodale épargnant la morphine : péridurale thoracique après laparotomie, ou lidocaïne IV continue [1+].", "Lever et alimentation orale avant la 24e heure ; sonde urinaire 24 h au plus après chirurgie colique [1+]."]'::jsonb),
  ('raac_lobectomie_pulmonaire_2019', '["Opérer dans un centre à haut volume ; pas d''hospitalisation systématique en réanimation.", "Information sur plusieurs supports et arrêt du tabac encouragé quelle que soit la date de l''intervention [1+].", "ALR postopératoire après thoracotomie [1+].", "Un seul drain thoracique, retiré le plus tôt possible ; colle ou patch en cas de fuite aérienne peropératoire [1+].", "Mobilisation précoce dans un programme de réhabilitation améliorée [1+]."]'::jsonb),
  ('raac_orthopedique_2019', '["Programme de récupération améliorée après prothèse de hanche ou de genou, pour réduire la durée de séjour [1+].", "Érythropoïétine préopératoire en cas d''anémie modérée (Hb 10 à 13 g/dL) [1+].", "Acide tranexamique périopératoire et prévention de l''hypothermie [1+].", "Analgésie locale ou locorégionale après prothèse de genou [1+].", "Thromboprophylaxie systématique après arthroplastie [1+]."]'::jsonb),
  ('recommandations_avk', '["Surdosage asymptomatique : conduite selon l''INR (tableau) ; INR 6 à 10 avec cible 2,5 : arrêt de l''AVK et 1 à 2 mg de vitamine K orale.", "INR ≥ 10 avec cible 2,5 : arrêt de l''AVK et 5 mg de vitamine K orale ; avis spécialisé si INR cible ≥ 3.", "Préférer la voie orale pour la vitamine K quand elle est possible [A].", "Prise en charge ambulatoire si possible, hospitalisation en cas de facteur de risque hémorragique individuel.", "Hémorragie grave : CCP et vitamine K ; relais héparinique avant chirurgie selon l''indication de l''AVK."]'::jsonb),
  ('reduction_antibiotiques_reanimation_2014', '["Faire les prélèvements bactériologiques si possible avant toute antibiothérapie, pour permettre une désescalade rapide.", "Ne pas traiter une simple colonisation, quel que soit le prélèvement.", "Pas de carbapénème en probabiliste pour une infection communautaire ; limiter quinolones et anti-SARM.", "Délais d''administration : moins d''1 h en cas de choc septique, moins de 3 h pour une méningite.", "Réévaluer à 48-72 h et raccourcir les durées (5 à 8 jours selon le site)."]'::jsonb),
  ('relations_anesth_chir', '["Chirurgien et anesthésiste-réanimateur forment une équipe : décision collective, responsabilité individuelle (art. 64).", "Échanger largement les informations, à l''oral et par écrit ; l''opérateur tient compte de l''avis de l''anesthésiste.", "Information loyale, claire et appropriée du patient, et consentement recherché dans tous les cas (art. 35 et 36).", "Organisation formalisée par une charte de fonctionnement (consultation, programme opératoire, SSPI).", "Nul médecin n''entreprend d''acte hors de sa compétence."]'::jsonb),
  ('remplissage', '["Sepsis ou choc septique : pas d''hydroxyéthylamidons [1-] ni de gélatines ; pas d''albumine en première intention.", "Cristalloïdes en première intention dans les états de choc.", "Les solutés balancés (Ringer lactate, Plasma-lyte, Isofundine) ont une composition proche du plasma, contrairement au NaCl 0,9 %.", "Choix du soluté précisé pour le choc hémorragique, le patient cérébrolésé et le péripartum."]'::jsonb),
  ('remplissage_perioperatoire', '["Patient chirurgical à haut risque : titrer le remplissage peropératoire sur le volume d''éjection systolique [1+].", "Arrêter le remplissage quand le VES n''augmente plus, et le réévaluer régulièrement [1+].", "Rachianesthésie pour césarienne : coremplissage par cristalloïdes et vasoconstricteur (phényléphrine) [1+].", "HEA : respecter les doses maximales et les éviter en cas de trouble de l''hémostase.", "PA, FC, diurèse et PVC reflètent mal le débit cardiaque."]'::jsonb),
  ('resection_hepatique_2025', '["Rechercher avant l''intervention anémie, troubles de l''hémostase, insuffisance rénale, cholestase, dénutrition et fragilité.", "Identifier les patients à risque d''insuffisance hépatique post-hépatectomie ; pas d''immunonutrition [G1].", "Sur foie sain, analgésie multimodale (paracétamol, AINS, opioïdes) [G1].", "Surveillance clinique et biologique rapprochée (bilirubine, TP, INR, facteur V) pour dépister une insuffisance hépatique.", "Résection carcinologique sans cirrhose : HBPM pendant 4 semaines [G1] ; réhabilitation améliorée."]'::jsonb),
  ('ressources_humaines_anesthesie_2024', '["Le médecin anesthésiste-réanimateur décide seul s''il prend en charge une ou au plus deux salles simultanément.", "La présence d''un IADE n''autorise pas à augmenter le nombre de patients par médecin.", "Deux salles simultanées doivent être assez proches pour une intervention sans délai.", "Exception : plus de deux patients possibles pour des ALR périphériques exclusives, sous surveillance d''un IDE formé.", "Procédures écrites de surveillance continue et de renfort en situation critique."]'::jsonb),
  ('sauv', '["La SAUV accueille tout patient en détresse vitale existante ou potentielle ; ouverte 24 h/24, elle doit être libérée dès que possible.", "Elle n''est ni un lit de réanimation ni un lieu d''hospitalisation.", "Située dans le service d''urgence ou à proximité immédiate, avec un accès direct au plateau technique.", "Équipement de niveau 1 (urgences hors SAU) ou de niveau 2 (SAU), surface d''au moins 25 m².", "Procédures écrites, collaboration avec le SAMU-SMUR et la réanimation, et évaluation régulière."]'::jsonb),
  ('sdra', '["Volume courant de 4 à 8 mL/kg de poids théorique et pression de plateau < 30 cmH2O [1+].", "SDRA sévère : décubitus ventral plus de 12 h par jour [1+].", "Pas de ventilation par oscillations à haute fréquence en routine [1-].", "SDRA modéré à sévère : PEP élevée et manœuvres de recrutement probablement recommandées.", "Pas de recommandation définitive sur l''ECMO veino-veineuse."]'::jsonb),
  ('securisation_proc', '["Un événement indésirable est une complication liée aux soins et non à la maladie ; il est grave s''il met en jeu le pronostic vital, prolonge le séjour ou laisse des séquelles.", "Standardiser le recueil des erreurs et des événements indésirables, et les classer selon leur gravité.", "Indicateurs de sécurité en nombre limité, définis selon un objectif, analysés régulièrement.", "Toute variation suspecte d''un indicateur impose une analyse systémique des causes.", "Procédures de sécurisation pour la ventilation, les abords vasculaires, les vasoactifs et l''épuration extrarénale."]'::jsonb),
  ('sedation_procedurale_2026', '["Ne pas associer midazolam et opiacés pour une sédation procédurale [1+].", "Pour réduire une fracture ou une luxation périphérique, préférer une anesthésie locale ou locorégionale par un médecin formé.", "Évaluer le patient avec le score ASA avant la sédation.", "Obésité morbide : patient à haut risque respiratoire ; titrer et doser les agents lipophiles sur le poids idéal.", "Capnographie et oxygénation pendant la sédation ; surveillance après la procédure avec des scores de sortie."]'::jsonb),
  ('sedation_reanimation', '["Éviter une sédation-analgésie insuffisante ou excessive ; l''évaluer régulièrement et tracer cette évaluation.", "Douleur : EVA chez le patient vigile, BPS ou ATICE chez le patient non communicant ; conscience : Ramsay, RASS ou ATICE.", "Propofol : moins de 48 h, moins de 5 mg/kg/h, et dépistage du syndrome de perfusion du propofol.", "En continu : morphine, fentanyl ou sufentanil ; bolus avant un geste douloureux.", "Réduire les doses en cas d''instabilité hémodynamique ; promouvoir les moyens non médicamenteux."]'::jsonb),
  ('sedation_urgences', '["Traiter toute douleur aiguë dès le début de la prise en charge, et l''évaluer puis la réévaluer (EVA, EN).", "Douleur intense (EVA ≥ 60 mm ou EN ≥ 6) : titration IV de morphine d''emblée.", "Naloxone titrée par bolus de 0,04 mg IV si sédation excessive, bradypnée < 10/min ou désaturation.", "Utiliser l''ALR quand elle est indiquée et réalisable.", "Patient intubé : sédation dès l''intubation, avec monitorage incluant la capnographie."]'::jsonb),
  ('sepsis', '["Le sepsis et le choc septique sont des urgences : traitement et réanimation immédiats, dosage du lactate.", "Choc septique ou forte probabilité de sepsis : antimicrobiens immédiatement, idéalement dans l''heure.", "Cristalloïdes en première ligne, noradrénaline en premier vasopresseur, PAM cible initiale de 65 mmHg.", "Contrôler le foyer infectieux dès que possible et retirer les dispositifs intravasculaires suspects.", "Réévaluer en permanence et arrêter les antimicrobiens si l''infection n''est pas confirmée."]'::jsonb),
  ('sepsis_hemodynamique', '["Choc septique : hypotension persistante malgré un remplissage de 20 à 40 mL/kg chez l''adulte.", "Remplissage vasculaire précoce dans le sepsis grave [B].", "Surveiller la diurèse horaire, la fonction rénale et la lactatémie.", "Vasoconstricteurs pour la vasoplégie ; inotropes réservés aux 10 à 20 % de patients en défaillance cardiaque.", "Stratégie en 3 étapes avec repères temporels (60 à 90 minutes, 6 heures)."]'::jsonb),
  ('sevrage_vm', '["Rechercher chaque jour, dès le début de la ventilation, les prérequis à l''épreuve de ventilation spontanée, selon un protocole écrit.", "Prérequis : pas de vasopresseur ni de sédation, réponse aux ordres simples, FiO2 ≤ 50 % et PEP ≤ 5 cmH2O.", "Épreuve de ventilation spontanée de 30 à 120 minutes, sous surveillance clinique et monitorée.", "Deux tiers des patients sont sevrés dès la première épreuve ; sevrage difficile en cas d''échec ou de reprise de ventilation dans les 48 h.", "BPCO et maladie neuromusculaire doublent au moins le risque de sevrage difficile."]'::jsonb),
  ('simulation_soins_critiques_2019', '["Utiliser la simulation pour apprendre les gestes techniques et maintenir les compétences, notamment lors de nouveaux matériels.", "Préférer la simulation basse fidélité pour les gestes techniques ; haute fidélité pour les compétences non techniques.", "Intégrer la simulation dans un curriculum, jamais comme méthode unique, et évaluer son impact.", "Gestes concernés : voies aériennes, cathéters veineux centraux et artériels, drain pleural.", "Débriefing systématique après chaque séance."]'::jsonb),
  ('sujet_age_esf', '["Évaluer le risque cardiovasculaire par le score de Lee, sans examens inutiles chez les patients peu à risque.", "Prise en charge orthogériatrique multidisciplinaire.", "Identifier et alléger les médicaments confusiogènes (benzodiazépines à demi-vie longue, anticholinergiques, tramadol…).", "Opérer une fracture de l''extrémité supérieure du fémur dans les 48 h suivant l''admission [1+].", "Monitorer la température ; réduire ou titrer les doses d''anesthésique local en rachianesthésie ; bloc fémoral ou iliofascial pour l''analgésie."]'::jsonb),
  ('tabagisme', '["Recommander systématiquement l''arrêt du tabac avant une chirurgie programmée, quel que soit le délai [1+].", "Proposer une prise en charge comportementale et une substitution nicotinique [1+].", "Arrêt plus de 8 semaines avant : environ -50 % de complications respiratoires ; plus de 4 semaines : environ -25 %.", "Tous les professionnels du parcours informent les fumeurs et proposent un suivi [1+].", "Éviter l''exposition de l''enfant au tabagisme passif avant l''intervention [1+]."]'::jsonb),
  ('tc_readaptation', '["Le score de Glasgow, avec une observation attentive, reste le meilleur outil pour suivre le passage du coma à l''éveil.", "La durée de l''amnésie post-traumatique (test GOAT) est le meilleur index pronostique initial.", "Consigner les échelles (GCS, GOAT, WHIM, GOS) et les rendre accessibles à toutes les unités successives.", "Potentiels évoqués cognitifs présents : forte valeur prédictive de l''éveil ; l''IRM est plus prédictive que la TDM.", "Transfert plus précoce vers la rééducation, idéalement dans une unité d''éveil dédiée."]'::jsonb),
  ('tenue_vestimentaire', '["Tenue dédiée au bloc opératoire, de préférence réutilisable.", "Ne pas quitter le bloc en tenue ; sinon la changer au retour, ou la couvrir d''une blouse fermée pour une sortie courte.", "Changer de tenue si elle est souillée, et au minimum chaque jour.", "Article coiffant couvrant toute la chevelure (charlotte, calot ou cagoule).", "Personnel non chirurgical : masque médical de type II ou IIR en salle d''intervention."]'::jsonb),
  ('tests_viscoelastiques', '["Les tests viscoélastiques (TEG®, ROTEM®) analysent la coagulation du sang total, plaquettes et fibrinolyse comprises.", "Rôle établi en traumatologie sévère et en chirurgie cardiaque ; encore à définir en obstétrique, en transplantation hépatique et en pédiatrie.", "En traumatologie, ils prédisent la transfusion et la transfusion massive (FIBTEM MCF < 7 mm, EXTEM A5).", "Les appareils ne sont pas interchangeables, ni corrélés parfaitement au TQ et au TCA ; prudence chez le patient hypotherme."]'::jsonb),
  ('thrombectomie', '["Anesthésie générale avec intubation si circulation postérieure, NIHSS ≥ 15, trouble de vigilance, agitation, vomissements ou détresse respiratoire.", "En dehors de ces situations, anesthésie locale ou sédation par une équipe d''anesthésie, sans privilégier l''anesthésie générale.", "Après la procédure : PAS entre 130 et 180 mmHg si recanalisation TICI < 2b, entre 130 et 160 mmHg si TICI ≥ 2b.", "SpO2 ≥ 95 % ; EtCO2 entre 35 et 40 mmHg sous anesthésie générale, capnographie continue sous sédation.", "Traiter l''hyperglycémie sans provoquer d''hypoglycémie."]'::jsonb),
  ('tih', '["Numération plaquettaire avant toute héparine (au plus tard avant J4) ; surveillance seulement si le risque de TIH est intermédiaire ou élevé.", "Contrôler les plaquettes devant tout événement inattendu sous héparine (thrombose, nécrose cutanée, réaction après injection).", "Évaluer la probabilité clinique par le score des 4T (hors chirurgie cardiaque).", "Score 4T ≤ 3 : TIH exclue sans test ; score intermédiaire ou élevé : rechercher les anticorps anti-FP4 au plus vite.", "TIH confirmée : arrêt de l''héparine et anticoagulant de substitution (danaparoïde, argatroban…)."]'::jsonb),
  ('tih_2002', '["La TIH de type II est immune et potentiellement grave, avec des thromboses veineuses ou artérielles.", "Elle survient typiquement 5 à 8 jours après le début de l''héparine, plus tôt en cas d''exposition dans les 3 mois.", "Évoquer le diagnostic devant des plaquettes < 100 G/L ou une baisse de plus de 40 %.", "Plus fréquente sous HNF en chirurgie (environ 3 %) que sous HBPM.", "Document historique : se reporter aux propositions GIHP/GFHT de 2019."]'::jsonb),
  ('tracheotomie', '["Pas de trachéotomie avant le 4e jour de ventilation mécanique [1-].", "Technique percutanée en standard [1+], par dilatation unique progressive.", "Indication en cas de sevrage prolongé ou de pathologie neuromusculaire acquise réversible ; concertation multidisciplinaire chez l''insuffisant respiratoire chronique.", "Contre-indications : instabilité hémodynamique, PIC > 15 mmHg, PaO2/FiO2 < 100 sous PEP > 10, troubles de l''hémostase non corrigés.", "Protocoles écrits pour la réalisation, les soins et la décanulation."]'::jsonb),
  ('transfusion_gr_anesth_2014', '["Seuil transfusionnel périopératoire de 7 g/dL sans antécédent particulier ; 8 à 9 g/dL en cas d''antécédent cardiovasculaire.", "10 g/dL en cas d''insuffisance coronarienne aiguë, d''insuffisance cardiaque avérée ou de mauvaise tolérance clinique.", "Corriger d''abord l''hypovolémie : la tolérance de l''anémie dépend du débit cardiaque.", "Polytraumatisme : acide tranexamique dans les 3 premières heures, 1 g en 10 min puis 1 g sur 8 h [A].", "EPO préopératoire en chirurgie orthopédique hémorragique en cas d''anémie modérée ; pas de facteur VIIa systématique."]'::jsonb),
  ('transfusion_plasma', '["Aucune préparation de plasma n''a démontré sa supériorité en efficacité.", "Transfuser au plus tard 6 heures après décongélation ou reconstitution ; la recongélation est interdite.", "Indications gradées en chirurgie, traumatologie et obstétrique, en médecine (CIVD, microangiopathies thrombotiques) et en pédiatrie.", "Le plasma n''est qu''un antidote exceptionnel du surdosage en AVK.", "Respecter la compatibilité ABO ; risques de TRALI et d''allergie."]'::jsonb),
  ('transport_intrahospitalier', '["Les patients à risque vital nécessitent souvent un transport intrahospitalier, source d''événements indésirables.", "Standardiser la définition des événements indésirables (graves ou porteurs de risque) et les surveiller.", "Un événement compliqué d''auto-extubation ou d''arrêt cardiaque est un événement indésirable grave.", "Matériel de transport adapté et entretenu, ventilateur de transport, monitorage de la capnographie.", "Préparer le patient avant le départ et organiser le transport par des soignants formés."]'::jsonb),
  ('traumatisme_abdominal', '["Ne pas se limiter à l''examen clinique pour affirmer ou exclure une lésion abdominale [1-].", "FAST à l''hôpital : une FAST positive affirme l''épanchement intrapéritonéal, une FAST négative élimine un hémopéritoine > 500 mL [1+].", "La FAST ne permet ni d''éliminer une lésion d''organe ni d''évaluer le rétropéritoine.", "Scanner thoraco-abdomino-pelvien injecté [1+], voire corps entier en cas de traumatisme grave.", "Laparotomie ou damage control selon l''état hémodynamique ; traitement non opératoire et embolisation selon les lésions."]'::jsonb),
  ('traumatisme_cranien', '["Abstention neurochirurgicale précoce chez un TC grave « dépassé » : décision collégiale, idéalement à trois médecins seniors (au moins deux en garde).", "Fragilité (mFI-5 ≥ 2, Clinical Frailty Scale ≥ 4), mydriase bilatérale aréactive ou traitement anticoagulant : facteurs de mauvais pronostic, sans contre-indiquer seuls la craniotomie.", "Le délai de prise en charge ne doit pas être pris en compte isolément dans la décision.", "L''aspirine en monothérapie n''est pas un facteur de mauvais pronostic et ne modifie pas l''indication opératoire.", "Recommandations spécifiques pour les hématomes extra- et sous-duraux, les embarrures et les traumatismes pénétrants."]'::jsonb),
  ('traumatisme_cranien_grave_precoce', '["Évaluer la gravité par le Glasgow (composante motrice) et les pupilles ; toute baisse de 2 points ou plus impose une nouvelle TDM en urgence [1+].", "Rechercher et traiter hypotension (PAS < 90 mmHg) et hypoxémie, qui aggravent fortement la mortalité [1+].", "Prise en charge préhospitalière médicalisée et orientation vers un centre avec neurochirurgie [1+] ; EtCO2 cible de 30 à 35 mmHg.", "TDM cérébrale et du rachis cervical sans délai chez tout TC grave ou modéré [1+].", "HTIC sévère ou engagement : mannitol 20 % ou sérum salé hypertonique en 15 à 20 min [1+] ; glycémie cible 8 à 11 mmol/L."]'::jsonb),
  ('traumatisme_cranien_leger', '["TC léger régulé : pas d''orientation systématique aux urgences si une personne peut surveiller le patient et en l''absence de facteur de risque.", "Risque élevé : trouble de l''hémostase (anticoagulant, double antiagrégation), signes de fracture du crâne, GCS < 15 à 2 h, vomissements répétés.", "Risque intermédiaire : protéine S100B dans les 3 h (ou UCH-L1 + GFAP dans les 12 h) pour limiter les scanners.", "L''aspirine ou le clopidogrel seuls ne sont plus des facteurs de risque de lésion hémorragique.", "À la sortie, information orale et écrite sur les signes devant faire reconsulter."]'::jsonb),
  ('traumatisme_membre', '["Tout patient présentant au moins un critère de Vittel est admis en centre de traumatologie grave [1+].", "Contrôler le saignement dès le préhospitalier, par garrot si nécessaire.", "Sans autre lésion grave ni instabilité : ostéosynthèse définitive des os longs dans les 24 premières heures [1+].", "Thromboprophylaxie précoce par HBPM après contrôle de l''hémorragie [1+].", "Rechercher une lésion vasculaire par imagerie injectée ; surveiller syndrome des loges et rhabdomyolyse."]'::jsonb),
  ('traumatisme_pelvien', '["Douleur pelvienne spontanée chez un patient conscient : fracture du bassin suspecte ; patient inconscient ou choqué : traumatisme pelvien présumé [1+].", "Contention pelvienne externe le plus tôt possible [1+].", "Transfert médicalisé vers un centre de référence [1+].", "Geste d''hémostase (embolisation ou tamponnement pré-péritonéal) dans les 60 minutes suivant l''admission [1+].", "Fixation externe précoce en cas d''instabilité hémodynamique (clamp de Ganz ou fixateur antérieur) [1+]."]'::jsonb),
  ('traumatisme_thoracique', '["Critères de gravité : plus de 2 fractures de côtes (surtout après 65 ans), détresse respiratoire ou circulatoire, terrain et cinétique.", "Au déchocage : échographie pleuropulmonaire, FAST et radiographie thoracique [1+] ; TDM thoracique injectée si critère de gravité.", "Hypoxémie à l''hôpital : VNI (VSAI-PEP) après TDM et drainage d''un pneumothorax si indiqué ; intubation si pas d''amélioration en 1 heure [1+].", "Ventilation mécanique : volume courant de 6 à 8 mL/kg de poids idéal, pression de plateau < 30 cmH2O [1+].", "Analgésie par ALR (bloc paravertébral, péridurale) selon le contexte."]'::jsonb),
  ('traumatisme_vertebromedullaire', '["Immobiliser précocement le rachis de tout traumatisé suspect de lésion rachidienne.", "Sans urgence vitale ni critère clinique (douleur rachidienne, trouble de conscience, déficit, intoxication) : pas d''immobilisation.", "Intubation : stabilisation manuelle dans l''axe, partie antérieure du collier retirée, sans manœuvre de Sellick.", "Corticothérapie contre-indiquée à la phase initiale ; orientation vers une filière spécialisée.", "Douleurs neuropathiques : gabapentinoïdes oraux au long cours, avec antidépresseur si besoin [1+]."]'::jsonb),
  ('urgences_ob_extrahosp', '["Le 15 est le seul numéro pour toute urgence obstétricale extrahospitalière.", "Accouchement en cours ou enfant né : départ réflexe d''une équipe SMUR et régulation médicale prioritaire.", "Scores de Malinas, SPIA et Prémat-SPIA pour aider à la régulation ; dilatation complète avec envie de pousser : accouchement sur place.", "Transport aux 2e et 3e trimestres en décubitus latéral, jamais en décubitus dorsal, avec voie veineuse.", "Urgence vitale maternelle : maternité la plus proche quel que soit le terme."]'::jsonb),
  ('urgences_obstetricales', '["Prédire l''imminence de l''accouchement (multiparité, antécédent d''accouchement rapide, contractions rapprochées, envie de pousser).", "Toucher vaginal avant de contacter la maternité si un médecin ou une sage-femme est présent.", "Pouvoir installer rapidement la patiente pour la manœuvre de McRoberts en cas de dystocie des épaules.", "Pas d''épisiotomie systématique hors structure spécialisée.", "Pré-éclampsie sévère et éclampsie : appliquer la RFE SFAR/CNGOF 2020 (antihypertenseurs, sulfate de magnésium)."]'::jsonb),
  ('urgences_transfusionnelles_obstetricales', '["Trois niveaux d''urgence : vitale immédiate (CGR sans délai, au besoin sans groupe), vitale (< 30 min, groupe conforme, au besoin sans RAI) et urgente (2 à 3 h).", "Le niveau d''urgence peut être requalifié à tout moment.", "Prévoir pendant la grossesse le typage érythrocytaire (ABO, Rh, Kell) et la RAI nécessaires à la sécurité transfusionnelle.", "Organisation formalisée entre maternité et site transfusionnel, avec évaluation régulière."]'::jsonb),
  ('urgences_vitales_ih_2026', '["Mettre en place une filière institutionnelle d''urgences vitales intrahospitalières, avec une procédure écrite et un référent.", "Procédure en 4 volets : détection précoce, activation, intervention et débriefing.", "Numéro d''appel unique, de préférence le 2222, accessible depuis tous les téléphones de l''hôpital.", "Réflexion anticipée sur le niveau d''engagement thérapeutique de chaque patient hospitalisé.", "Chariots d''urgence standardisés, registre, RMM et formation aux gestes d''urgence."]'::jsonb),
  ('vni', '["VNI recommandée dans la décompensation de BPCO avec acidose (pH < 7,35), l''OAP cardiogénique, l''IRA de l''immunodéprimé et après chirurgie thoracique ou abdominale.", "OAP cardiogénique : VNI associée au traitement médical optimal ; en préhospitalier, VS-PEP.", "Respecter les contre-indications absolues (coma non hypercapnique, choc, épuisement, pneumothorax non drainé, patient non coopérant…).", "Surveillance clinique rapprochée, surtout pendant la première heure, avec la fréquence respiratoire.", "VNI possible en préoxygénation et chez les patients pour qui l''intubation n''est pas envisagée."]'::jsonb),
  ('voies_aeriennes_adulte', '["Prédire une intubation difficile : Mallampati > 2, distance thyromentale < 65 mm, ouverture de bouche < 35 mm.", "Prédire une ventilation au masque difficile : âge > 55 ans, IMC > 26 kg/m², édentation, ronflements, barbe.", "Rechercher conjointement les deux types de difficulté, dont l''association est la plus critique.", "Un curare à dose suffisante (≥ 2 DA95) améliore les conditions d''intubation ; monitorer son délai d''action.", "Actualisé en 2026 par la recommandation sur les voies aériennes de l''adulte au bloc opératoire."]'::jsonb),
  ('voies_aeriennes_bloc_2026', '["Sans critère d''intubation difficile : vidéolaryngoscope en première intention plutôt que laryngoscope direct [1+], avec un curare.", "Sans risque d''estomac plein : préférer les dispositifs supraglottiques de 2e génération à l''intubation quand la chirurgie le permet.", "Oxygénation apnéique en cas de difficulté prévue ; cricothyroïdotomie en situation « impossible d''intuber, impossible d''oxygéner ».", "Briefing, simulation et maintien des compétences des équipes.", "Actualise la RFE 2017 sur l''intubation difficile et le consensus de 2002-2003."]'::jsonb),
  ('voies_aeriennes_enfant', '["Préférer les sondes à ballonnet, avec une pression du ballonnet ≤ 20 cmH2O [1+] ; sonde à ballonnet pour l''amygdalectomie.", "Intubation et ventilation difficiles imprévues : dispositif supraglottique pour oxygéner l''enfant [1+].", "Pression du coussinet d''un dispositif supraglottique limitée à 40 cmH2O, contrôlée au manomètre [1+].", "Induction en séquence rapide : curare d''action rapide [1+].", "Enfant enrhumé : masque facial si l''urgence, le type et la durée de la chirurgie le permettent [1+]."]'::jsonb)
) as v(fiche_key, points)
join public.documents d on d.fiche_key = v.fiche_key
on conflict (document_id) do nothing;
